import gurobipy as gp
from gurobipy import GRB
workstations = [1, 2, 3]
models = list(range(1, 102))
capacities = {1: 1296.0, 2: 1238.4, 3: 1267.2}
t = {1: [8.0, 7.5, 8.2, 7.8, 8.1, 7.9, 8.3, 8.0, 7.7, 8.2, 8.1, 7.8, 8.0, 8.2, 7.9, 8.1, 8.0, 7.7, 8.3, 8.1, 7.8, 8.0, 8.2, 7.9, 8.1, 8.0, 7.7, 8.3, 8.1, 7.8, 8.0, 8.2, 7.9, 8.1, 8.0, 7.7, 8.3, 8.1, 7.8, 8.0, 8.2, 7.9, 8.1, 8.0, 7.7, 8.3, 8.1, 7.8, 8.0, 8.2, 7.9, 8.1, 8.0, 7.7, 8.3, 8.1, 7.8, 8.0, 8.2, 7.9, 8.1, 8.0, 7.7, 8.3, 8.1, 7.8, 8.0, 8.2, 7.9, 8.1, 8.0, 7.7, 8.3, 8.1, 7.8, 8.0, 8.2, 7.9, 8.1, 8.0, 7.7, 8.3, 8.1, 7.8, 8.0, 8.2, 7.9, 8.1, 8.0, 7.7, 8.3, 8.1, 7.8, 8.0, 8.2, 7.9, 8.1, 8.0, 7.7, 8.3, 8.1], 2: [9.0, 8.7, 9.1, 8.8, 9.0, 8.9, 9.2, 9.0, 8.8, 9.1, 9.0, 8.8, 9.0, 9.1, 8.9, 9.0, 9.0, 8.8, 9.2, 9.0, 8.8, 9.0, 9.1, 8.9, 9.0, 9.0, 8.8, 9.2, 9.0, 8.8, 9.0, 9.1, 8.9, 9.0, 9.0, 8.8, 9.2, 9.0, 8.8, 9.0, 9.1, 8.9, 9.0, 9.0, 8.8, 9.2, 9.0, 8.8, 9.0, 9.1, 8.9, 9.0, 9.0, 8.8, 9.2, 9.0, 8.8, 9.0, 9.1, 8.9, 9.0, 9.0, 8.8, 9.2, 9.0, 8.8, 9.0, 9.1, 8.9, 9.0, 9.0, 8.8, 9.2, 9.0, 8.8, 9.0, 9.1, 8.9, 9.0, 9.0, 8.8, 9.2, 9.0, 8.8, 9.0, 9.1, 8.9, 9.0, 9.0, 8.8, 9.2, 9.0, 8.8, 9.0, 9.1, 8.9, 9.0, 9.0, 8.8, 9.2, 9.0], 3: [7.5, 7.2, 7.6, 7.3, 7.5, 7.4, 7.7, 7.5, 7.3, 7.6, 7.5, 7.3, 7.5, 7.6, 7.4, 7.5, 7.5, 7.3, 7.7, 7.5, 7.3, 7.5, 7.6, 7.4, 7.5, 7.5, 7.3, 7.7, 7.5, 7.3, 7.5, 7.6, 7.4, 7.5, 7.5, 7.3, 7.7, 7.5, 7.3, 7.5, 7.6, 7.4, 7.5, 7.5, 7.3, 7.7, 7.5, 7.3, 7.5, 7.6, 7.4, 7.5, 7.5, 7.3, 7.7, 7.5, 7.3, 7.5, 7.6, 7.4, 7.5, 7.5, 7.3, 7.7, 7.5, 7.3, 7.5, 7.6, 7.4, 7.5, 7.5, 7.3, 7.7, 7.5, 7.3, 7.5, 7.6, 7.4, 7.5, 7.5, 7.3, 7.7, 7.5, 7.3, 7.5, 7.6, 7.4, 7.5, 7.5, 7.3, 7.7, 7.5, 7.3, 7.5, 7.6, 7.4, 7.5, 7.5, 7.3, 7.7, 7.5]}
for w in workstations:
    if len(t[w]) != 101:
        raise ValueError(f'Processing time list for workstation {w} does not have 101 entries.')
m = gp.Model('radio_idle_time_min')
x_vars = m.addVars(models, lb=0, vtype=GRB.INTEGER, name='')
I_vars = m.addVars(workstations, lb=0.0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((I_vars[w] for w in workstations)), GRB.MINIMIZE)
for w in workstations:
    m.addConstr(I_vars[w] + gp.quicksum((t[w][m_idx - 1] * x_vars[m_idx] for m_idx in models)) == capacities[w], name=f'idle_def_w{w}')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')